        $before=$this->state();$r=(new LegacyOfficerPersonnelBackfillService($this->legacy,$this->pdo))->dryRun();$this->same(6429,$r['target_officers_examined'],'all target Officers examined');$this->same(6429,$r['target_officers_mapped'],'all Officers mapped by legacy reference');$this->same(0,$r['would_update'],'execute rerun is idempotent');$this->same(0,$r['true_blockers'],'no identity blockers');$this->same(2,$r['permanency_unknown'],'ambiguous Select permanency remains unknown');$this->same(true,$r['alias_field_conflicts']>0,'conflicting alias fields are reported');$this->same($before,$this->state(),'dry-run makes no operational writes');
        $this->same(0,$this->scalar("SELECT COUNT(*) FROM officer o JOIN legacy_officer_reference r ON r.officer_id=o.id JOIN dems_legacy_hr.tbl_officer lo ON lo.officer_id=r.legacy_officer_id WHERE TRIM(lo.permanent_or_not)='Yes' AND o.arpa_service_permanency<>'PERMANENT_IN_SERVICE'"),'Yes maps to permanent in service');$this->same(0,$this->scalar("SELECT COUNT(*) FROM officer o JOIN legacy_officer_reference r ON r.officer_id=o.id JOIN dems_legacy_hr.tbl_officer lo ON lo.officer_id=r.legacy_officer_id WHERE TRIM(lo.permanent_or_not)='No' AND o.arpa_service_permanency<>'NOT_PERMANENT_IN_SERVICE'"),'No maps to not permanent in service');
