    private function nicAndScope():void
    {
        $this->same('735190431V',NicNormalizer::normalize(' 735190431v '),'old NIC normalization is case-safe');$this->same('196566110037',NicNormalizer::normalize('196566110037'),'modern NIC normalization supported');$context=$this->pdo->query("SELECT su.id user_id,uar.id role_assignment_id,uas.id scope_assignment_id FROM system_user su JOIN user_account_role uar ON uar.user_id=su.id JOIN application_role r ON r.id=uar.role_id AND r.role_code='ASC_SUBJECT_OFFICER' JOIN user_account_scope uas ON uas.role_assignment_id=uar.id AND uas.user_id=uar.user_id JOIN location l ON l.id=uas.location_id AND l.dad_number='70004-0000389' WHERE su.username='asctest' AND uar.active=1 AND uar.approval_status='APPROVED' AND uas.active=1 AND uas.approval_status='APPROVED' LIMIT 1")->fetch();if(!$context)throw new RuntimeException('asctest ASC Subject Officer context is required.');$user=(string)$context['user_id'];$_SESSION=['user_id'=>$user,'authenticated_at'=>time(),'last_activity_at'=>time()];(new UserContextService($this->pdo))->select($user,(string)$context['role_assignment_id'],(string)$context['scope_assignment_id']);Auth::forgetRequestCache();$access=ScopeService::currentOfficerAccess($user,'o.id');$s=$this->pdo->prepare($access['with']." SELECT o.id,o.nic FROM officer o WHERE ".implode(' AND ',$access['where'])." AND o.nic_normalized=?");$s->execute(array_merge($access['params'],['735190431V']));$visible=$s->fetch();$this->same(true,(bool)$visible,'scoped old-format NIC is searchable');$this->same(true,ScopeService::canAccessOfficer($user,$visible['id']),'own scoped Officer is accessible');$outside=(string)$this->pdo->query("SELECT id FROM officer WHERE id<>'{$visible['id']}' ORDER BY dad_number LIMIT 1")->fetchColumn();$this->same(false,ScopeService::canAccessOfficer($user,$outside),'unrelated Officer direct access rejected');
        $definition=DataTableRegistry::definition('officers');$response=(new DataTableQuery($this->pdo,$definition,new DataTableRequest(['length'=>25,'search'=>['value'=>'735190431v']])))->response();$this->same(1,$response['recordsFiltered'],'DataTable NIC search is scoped and case-insensitive under collation');$this->same(true,in_array('Current Assignments',array_column($definition['columns'],'label'),true),'Officer list exposes current assignments');$searchView=file_get_contents(BASE_PATH.'/app/Views/officers/search.php');$this->contains('method="post"',$searchView,'NIC is never placed in a URL query string');$this->contains('Csrf::field()',$searchView,'NIC search is CSRF protected');$this->contains('Matching Officers',$searchView,'ambiguous NIC results provide a selection list');
    }
    private function profile():void
